import numpy as np


class Matrix:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def zeros(rows, cols):
        row = [0] * cols
        return Matrix([row] * rows)


def to_ndarray(columns):
    return np.stack(columns)


def from_ndarray(arr, chunk_size):
    chunks = []
    for start in range(0, arr.shape[0] // chunk_size * chunk_size, chunk_size):
        chunks.append(arr[start:start + chunk_size])
    return chunks
